const CACHE='tuka-v16';const SHELL=['./community.js?v=16','./community-config.json','./ticket.js?v=16','./','./index.html','./boot.js?v=16','./layout.js?v=16','./install.js?v=16','./style.css?v=16','./app.js?v=16','./transit.js?v=16','./live.js?v=16','./map-ui.js?v=16','./stop-network.js?v=16','./ride.js?v=16','./icon.svg','./manifest.webmanifest','./vendor/maplibre-gl.js','./vendor/maplibre-gl.css','./icon-192-blue.png','./icon-512-blue.png'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE&&k!=='tuka-schedule').map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(url.origin!==self.location.origin||url.pathname.startsWith('/api/'))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request)))});
